import json
import sys
import time
import urllib.error
import urllib.request

BASE = "http://localhost:8080"
LOG = sys.stderr


def request(method, path, token=None):
    """Return (status, headers, body_text). Retries transient failures."""
    attempt = 0
    while True:
        attempt += 1
        headers = {}
        if token:
            headers["Authorization"] = "Bearer " + token
        req = urllib.request.Request(BASE + path, method=method, headers=headers)
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                return resp.status, resp.headers, resp.read().decode()
        except urllib.error.HTTPError as e:
            body = e.read().decode(errors="replace")
            if e.code == 429:
                wait = float(e.headers.get("Retry-After", "1"))
                print(f"429 on {path}, waiting {wait}s: {body[:200]}", file=LOG)
                time.sleep(wait)
                continue
            if e.code == 404:
                return e.code, e.headers, body
            if e.code in (401, 403):
                print(f"{e.code} on {path}: {body[:200]}", file=LOG)
                return e.code, e.headers, body
            print(f"HTTP {e.code} on {path} (attempt {attempt}): {body[:200]}", file=LOG)
        except (urllib.error.URLError, TimeoutError, ConnectionError) as e:
            print(f"transport error on {path} (attempt {attempt}): {e}", file=LOG)
        if attempt >= 20:
            raise RuntimeError(f"giving up on {path}")
        time.sleep(min(2 ** attempt, 10))


class Auth:
    def __init__(self):
        self.token = None
        self.refreshes = 0

    def get(self):
        if self.token is None:
            self.refresh()
        return self.token

    def refresh(self):
        status, _, body = request("POST", "/token")
        self.token = json.loads(body)["token"]
        self.refreshes += 1
        print(f"token refresh #{self.refreshes}", file=LOG)


def authed(auth, method, path):
    """Authenticated request that refreshes the token on 401 and retries."""
    for _ in range(10):
        status, headers, body = request(method, path, auth.get())
        if status == 401:
            auth.refresh()
            continue
        return status, headers, body
    raise RuntimeError(f"still unauthorised for {path}")


def fetch_orders(auth):
    pages = []
    page = 1
    total = None
    while True:
        status, _, body = authed(auth, "GET", f"/orders?page={page}")
        if status != 200:
            raise RuntimeError(f"orders page {page} returned {status}")
        data = json.loads(body)
        pages.append({"page": page, "items": data["items"]})
        total = data["total_pages"]
        print(f"page {page}/{total}: {len(data['items'])} items", file=LOG)
        if data.get("next") is None:
            break
        page += 1
    return pages, total


def fetch_customers(auth, ids):
    out = {}
    for cid in sorted(ids):
        status, _, body = authed(auth, "GET", f"/customers/{cid}")
        if status != 200:
            raise RuntimeError(f"customer {cid} returned {status}: {body[:200]}")
        out[cid] = json.loads(body)
    return out


if __name__ == "__main__":
    auth = Auth()
    pages, total = fetch_orders(auth)
    if len(pages) != total:
        raise SystemExit(f"expected {total} pages, got {len(pages)}")
    cids = {it["customer_id"] for p in pages for it in p["items"]}
    print(f"distinct customers referenced: {len(cids)}", file=LOG)
    customers = fetch_customers(auth, cids)
    with open("/tmp/recon/raw.json", "w") as f:
        json.dump({"pages": pages, "customers": customers}, f)
    print("saved /tmp/recon/raw.json", file=LOG)

